   286→/**
   287→ * Eliminar empresas.
   288→ *
   289→ * @returns {void}
   290→ * @author Daniel Beltrán
   291→ * @author Fahibram Cárcamo
   292→ */
   293→async function eliminarEmpresas(empresa_id = null) {
   294→    await $.ajax({
   295→        type: 'DELETE',
   296→        url: `/empresas/${empresa_id}`,
   297→        data: { _token: $('meta[name="csrf-token"]').attr('content') }
   298→    }).then(respuesta => {
   299→        sucursal_id_eliminar = null;
   300→        if (respuesta.tipo != undefined && respuesta.tipo == 'success') {
   301→            mostrarToast('success', respuesta.mensaje);
   302→            mostrarTablaSucursales();
   303→        } else if (respuesta.errors != undefined) {
   304→            mostrarToast('danger', respuesta.message);
   305→        }
   306→        $('#modal-confirmar-eliminacion').modal('hide');
   307→    }).catch((error) => {
   308→        mostrarToast('danger', error.responseJSON.errors);
   309→        sucursal_id_eliminar = null;
   310→        $('#modal-confirmar-eliminacion').modal('hide');
   311→    });
   312→}
