   363→            $('#departamento_id').append(`<option></option>`);
   364→            datos.forEach((item) => {
   365→                $('#departamento_id').append(new Option(item.nombre, item.id));
   366→            });
   367→            if ($(this).data('departamento_id') != '') {
   368→                $('#departamento_id').val($(this).data('departamento_id')).trigger('change');
   369→            }
   370→        }).catch((error) => {
