   435→/**
   436→ * Mostrar la tabla con los datos de los usuarios.
   437→ *
   438→ * @return {void}
   439→ * @author Fahibram Cárcamo
   440→ */
   441→function mostrarUsuarios() {
   442→    let filtrar_usuarios = $('#filtrar-usuarios').val();
   443→    if ($.fn.DataTable.isDataTable('#tabla-usuarios')) {
   444→        tabla_usuarios.destroy();
   445→    }
   446→    $('#buscador-usuario').remove();
   447→    $('#tbody-usuarios').empty();
   448→    for (let i = 0; i < usuarios.length; i++) {
   449→        if (
   450→            usuarios[i].usuario != undefined &&
   451→            (
   452→                (filtrar_usuarios == 'Todos') ||
   453→                (filtrar_usuarios == '1' && usuarios[i].usuario.estado.id == 1) ||
   454→                (filtrar_usuarios == '2' && usuarios[i].usuario.estado.id == 2)
