   462→                        <label for="check-estado-usuario-${usuarios[i].usuario.id}" class="custom-switch-label"></label>
   463→                    </div>
   464→                </div>
   465→            `;
   466→            if (usuarios[i].usuario.estado.id == 1) {
   467→                estado = `
   468→                    <div class="col-12 text-gray-30 text-end">
   469→                        <span class="me-3">Activo</span>
   470→                        <div class="custom-switch">
   471→                            <input type="checkbox" id="check-estado-usuario-${usuarios[i].usuario.id}" class="custom-switch-input" onclick="activarOInactivarUsuarios(this.checked, ${usuarios[i].usuario.id})" checked>
   472→                            <label for="check-estado-usuario-${usuarios[i].usuario.id}" class="custom-switch-label"></label>
   473→                        </div>
   474→                    </div>
   475→                `;
   476→            }
   477→            let checked = '';
   478→            if (usuarios_seleccionados.includes(usuarios[i].usuario.id)) {
   479→                checked = 'checked';
   480→            }
   481→            $('#tbody-usuarios').append(`
   482→                <tr>
   483→                    <td style="border-bottom: 0px!important;">
   484→                        <div class="border border-1 rounded rounded-3">
   485→                            <div class="row m-0 w-100 px-3 py-5 text-headline-6 align-items-center">
   486→                                <div class="col-auto">
   487→                                    <div class="check-container my-1 me-1">
   488→                                        <input type="checkbox" class="form-check-input" value="${usuarios[i].usuario.id}" ${checked} onclick="seleccionarUsuario(this.value, this.checked);">
   489→                                    </div>
   490→                                </div>
   491→                                <div class="col-auto w-120px px-0 text-center text-headline-7 text-gray-30">
   492→                                    <div class="row justify-content-center mb-1">
   493→                                        <div class="imagen-usuario" style="background-image: url(/usuarios-imagen/${usuarios[i].usuario.id})"></div>
   494→                                    </div>
   495→                                    ${usuarios[i]?.usuario?.ciudad?.nombre ?? ''}, ${usuarios[i]?.usuario?.ciudad?.departamento?.pais.nombre ?? ''}
   496→                                </div>
   497→                                <div class="col ps-lg-4">
   498→                                    <div class="row w-100 mx-0">
   499→                                        <div class="col-12 mb-0 text-gray-10 text-headline-5">
   500→                                            ${usuarios[i].usuario.nombres} ${usuarios[i].usuario.apellidos} | <span class="text-headline-7 mb-0">${obtenerEdad(usuarios[i].usuario.fecha_nacimiento)}</span>
   501→                                        </div>
   502→                                        <div class="col-12 mt-2 text-gray-50 text-headline-7">
   503→                                            Rol: ${usuarios[i]?.rol?.name ?? ''} <span class="ms-3">Cargo:</span> ${usuarios[i]?.usuario?.cargo?.nombre ?? ''}
   504→                                        </div>
   505→                                        <div class="col-12 mt-3 text-gray-30 text-headline-7">
   506→                                            <i class="bi bi-envelope me-1"></i> ${usuarios[i]?.usuario?.email} <i class="bi bi-telephone ms-4 me-1"></i> ${usuarios[i]?.usuario?.telefono}
   507→                                        </div>
   508→                                        <div class="col-12 mt-1 text-gray-30 text-headline-7">
   509→                                            <i class="bi bi-person-vcard me-1"></i> ${usuarios[i]?.usuario?.tipo_documento?.abreviatura} ${usuarios[i]?.usuario?.documento}
   510→                                        </div>
   511→                                    </div>
   512→                                </div>
   513→                                <div class="col-auto">
