   615→ * @return {string}
   616→ * @author José Manuel Jiménez
   617→ */
   618→function obtenerEdad(fecha_nacimiento) {
   619→    if (!fecha_nacimiento) {
   620→        return "";
   621→    }
   622→    const hoy = new Date();
   623→    const nacimiento = new Date(fecha_nacimiento);
   624→    let edad = hoy.getFullYear() - nacimiento.getFullYear();
   625→    const mes = hoy.getMonth() - nacimiento.getMonth();
   626→    if (mes < 0 || (mes === 0 && hoy.getDate() < nacimiento.getDate())) {
   627→        edad--;
   628→    }
   629→    return edad + " años";
   630→}
