let cantidad_sucursales = 0;
let sucursales = [];
let empresa = null;

const COLUMNAS_DATATABLE = [
    { orderable: false, searchable: false },
    { data: 'nombre_comercial' },
    { data: 'documento' },
    { data: 'ciudad.nombre' },
