    { data: 'direccion' },
    { data: 'telefono' },
    { data: 'sector.nombre' },
    { data: 'created_at' },
    { data: 'numero_empleados' },
    { name: 'acciones', orderable: false, searchable: false }
];

let resource_url = 'empresas';
if (resource_url == undefined) {
    redirige_form = 'empresas';
}
let usuarios_seleccionados = [];
let url_datatable = {
    url: resource_url + '-listado-tabla',
};
let actualizar_configuracion = false;
usuario_id_eliminar = null;
usuario_nombre_eliminar = '';

//APARTADO PARA GESTIONAR EMPRESAS
let usuarios = [];
let empresa_seleccionada = null;

const configuracion_tablas = {
    autoWidth: false,
    responsive: true,
    processing: false,
    serverSide: true,
    searching: true,
    deferRender: true,
    paging: true,
    aaSorting: [],
    language: lenguaje_componente_datatables,
