    scrollY: 'calc(100vh - 450px)',
    scrollCollapse: true,
};

$(document).ready(function () {
    obtenerFuncionalidadesActivasPlan();

    $('#boton-crear-sucursal').on('click', () => {
        if (!buscarFuncionalidad('multi_sucursal')) {
            modalFuncionalidadInactiva();
            return;
        }

        window.location.href = `/sucursales/create?empresa_id=${empresa.id}`;
    });
});

/**
 * Función que inicializa la tabla de sucursales usando DataTable con AJAX.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Fahibram Cárcamo
 */
function mostrarTablaSucursales() {
    // Destruir tabla existente si existe
    if ($.fn.DataTable.isDataTable(`#${id_tabla_sucursales}`)) $(`#${id_tabla_sucursales}`).DataTable().destroy();

    // Configurar e inicializar DataTable
    tabla_sucursales = $(`#${id_tabla_sucursales}`).DataTable({
        ...configuracion_tablas,
        ajax: {
            url: '/empresas-listado-sucursales',
            data: function (datos) {
                datos.departamento_id = $('#departamento_id').val();
                datos.ciudad_id = $('#ciudad_id').val();
                datos.pais_id = $('#pais_id').val();

                let rango_fechas = $('#filtro_fecha_hora').val();
                if (rango_fechas !== '') datos.rango_fechas = rango_fechas.split(" a ");
            },
            dataSrc: function(json) {
                sucursales = Object.values(json.data);
                cantidad_sucursales = sucursales.length;
                return Object.values(json.data);
            }
        },
        columns: [
            {
                title: `${
                    crearCheckbox({
                        id: 'checkbox-seleccionar-todas-sucursales-empresa',
                        name: 'checkbox-seleccionar-todas-sucursales-empresa',
                        onchange: 'seleccionarTodasSucursales(this.checked)'
                    })
                }`,
                data: 'id',
                orderable: false,
                searchable: false,
                render: (data) => {
                    return  crearCheckbox({
                        id: `${data}`,
                        class: 'checkbox-sucursal',
                        name: 'checkbox-sucursal',
                        checked: sucursales_seleccionadas.includes(data),
                        onchange: `seleccionarCheckboxEmpresa(this.checked, ${data})`,
                    })
                }
            },
            {
                title: '<span class="text-body-3">Nombre comercial</span>',
                data: 'nombre_comercial',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">NIT</span>',
                data: 'documento',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">Ciudad</span>',
                data: 'ciudad.nombre',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">País</span>',
                data: 'ciudad.departamento.pais.nombre',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">Dirección</span>',
                data: 'direccion',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">Celular</span>',
                data: 'celular',
                className: 'text-body-3',
                orderable: true,
                searchable: true
            },
            {
                title: '<span class="text-body-3">Sector</span>',
                data: 'sector.nombre',
                className: 'text-body-3',
                orderable: true,
                searchable: true,
                visible: $('#columna-sector').is(':checked')
            },
            {
                title: '<span class="text-body-3">Número de empleados</span>',
                data: 'conteo_empleados',
                className: 'text-body-3 text-center',
                orderable: true,
                searchable: true,
                visible: $('#columna-numero-empleados').is(':checked')
            },
            {
                title: '<span class="text-body-3">Fecha de creación</span>',
                data: 'created_at',
                className: 'text-body-3',
                orderable: true,
                searchable: true,
                visible: $('#columna-fecha-creacion').is(':checked'),
                render: (data, type) => (type === 'display') ? (moment(data).format('YYYY-MM-DD') ?? '---') : data
            },
            {
                title: '<span class="text-body-3">Acciones</span>',
                data: null,
                className: 'text-body-3 text-center',
                orderable: false,
                searchable: false,
                render: function (data, type, row) {
                    return `
                        <div class="col-auto px-0 dropdown">
                            <i class="bi bi-three-dots dropdown-toggle text-blue-40 pointer" data-bs-toggle="dropdown" data-bs-auto-close="outside" aria-expanded="false"></i>
                            <div class="dropdown-menu">
                                <a href="/empresas/${row.id}/edit" class="dropdown-item no-visited pointer py-2">Editar sucursal</a>
                                <a href="/usuarios/create?empresa_id=${row.id}" class="dropdown-item no-visited pointer py-2">Crear usuario</a>
                                <div
                                    class="dropdown-item no-visited pointer py-2"
                                    onclick="abrirModalConfirmarEliminarSucursal('${row?.id}', '${row?.nombre_comercial}')"
                                >
                                    <p class="text-danger mb-0">Eliminar</p>
                                </div>
                            </div>
                        </div>
                    `;
                }
            }
        ],
        initComplete: function () {
            cargarDataTablas();
        },
