/**
 * Eliminar empresas.
 *
 * @returns {void}
 * @author Daniel Beltrán
 * @author Fahibram Cárcamo
 */
async function eliminarEmpresas(empresa_id = null) {
    await $.ajax({
        type: 'DELETE',
        url: `/empresas/${empresa_id}`,
        data: { _token: $('meta[name="csrf-token"]').attr('content') }
    }).then(respuesta => {
        sucursal_id_eliminar = null;
        if (respuesta.tipo != undefined && respuesta.tipo == 'success') {
            mostrarToast('success', respuesta.mensaje);
            mostrarTablaSucursales();
        } else if (respuesta.errors != undefined) {
            mostrarToast('danger', respuesta.message);
        }
        $('#modal-confirmar-eliminacion').modal('hide');
    }).catch((error) => {
        mostrarToast('danger', error.responseJSON.errors);
        sucursal_id_eliminar = null;
        $('#modal-confirmar-eliminacion').modal('hide');
    });
}

