 */
function seleccionarTodosUsuarios(checked) {
    usuarios_seleccionados = [];
    if (checked) {
        for (let i = 0; i < usuarios.length; i++) {
            usuarios_seleccionados.push(usuarios[i].usuario.id);
        }
    }
    mostrarUsuarios();
}

/**
 * Selecciona o deselecciona un usuario.
 *
 * @param {int} usuario_id Id del usuario.
 * @param {boolean} checked Chequear o deschequear.
 * @return {void}
 * @author Fahibram Cárcamo
 */
function seleccionarUsuario(usuario_id, checked) {
    if (checked) {
        if (!usuarios_seleccionados.includes(parseInt(usuario_id))) {
            usuarios_seleccionados.push(parseInt(usuario_id));
        }
    } else {
        usuarios_seleccionados = usuarios_seleccionados.filter(id => id !== parseInt(usuario_id));
    }
    validarCheckUsuariosSeleccionados();
}

/**
 * Validar el check de los usuarios seleccionados.
 *
 * @return {void}
 * @author Fahibram Cárcamo.
 */
function validarCheckUsuariosSeleccionados() {
    if (usuarios_seleccionados.length == 0) {
        $('#checkbox-seleccionar-todas-sucursales-empresa').prop('indeterminate', false);
        $('.botones-usuarios').prop('disabled', true);
        $('#checkbox-seleccionar-todas-sucursales-empresa').prop('checked', false);
    } else if (usuarios_seleccionados.length == usuarios.length) {
        $('.botones-usuarios').prop('disabled', false);
        $('#checkbox-seleccionar-todas-sucursales-empresa').prop('indeterminate', false);
        $('#checkbox-seleccionar-todas-sucursales-empresa').prop('checked', true);
    } else {
        $('.botones-usuarios').prop('disabled', false);
        $('#checkbox-seleccionar-todas-sucursales-empresa').prop('indeterminate', true);
    }
    $('#cantidad-seleccionados').text(usuarios_seleccionados.length);
}

/**
 * Función para obtener edad actual de un usuario segun su fecha de nacimiénto
 *
 * @param {string} fecha_nacimiento
 * @return {string}
 * @author José Manuel Jiménez
 */
function obtenerEdad(fecha_nacimiento) {
    if (!fecha_nacimiento) {
        return "";
    }
    const hoy = new Date();
    const nacimiento = new Date(fecha_nacimiento);
    let edad = hoy.getFullYear() - nacimiento.getFullYear();
    const mes = hoy.getMonth() - nacimiento.getMonth();
    if (mes < 0 || (mes === 0 && hoy.getDate() < nacimiento.getDate())) {
        edad--;
    }
    return edad + " años";
}

