/**
 * Actualizar la configuración de la empresa.
 *
 * @param {any} valor valor a actualizar en la configuración seleccionada.
 * @param {int} configuracion_id id de configuración a actualizar.
 * @returns {Promise<void>}
 * @author Daniel Beltrán, José Manuel Jiménez
 */
async function actualizarConfiguracion(valor, configuracion_id) {
    if (actualizar_configuracion) {
        if (configuracion_id == 1 || configuracion_id == 2) {
            if (valor != 'todos' && valor != 'administradores') {
                if (valor == '[]') {
                    mostrarToast('neutral', `Selecciona al menos un usuario`);
                    return false;
                } else if (valor == 'Elegir usuarios') {
                    return false;
                }
            }
        }
        await $.ajax({
            type: 'POST',
            url: `/configuraciones-modelos`,
            data: {
                _token: $('meta[name="csrf-token"]').attr('content'),
                model_type: 'App\\Models\\Empresas\\Empresa',
                modelo_id: empresa_seleccionada.id,
                configuracion_id: configuracion_id,
                valor: valor
            }
        }).then((respuesta) => {
            mostrarToast('success', respuesta.message);
            datos = respuesta.data || [];
        }).catch((error) => {
            console.error(error);
        });
    }
}

